def block_code(self, token: Dict[str, Any], state: BlockState) -> str:
    attrs = token.get("attrs", {})
    info = cast(str, attrs.get("info"))
    code = indent(cast(str, token["raw"]), "   ")
    if info:
        lang = info.split()[0]
        return '.. code:: ' + lang + '\n\n' + code + '\n\n'
    else:
        return '::\n\n' + code + '\n\n'
